public final class ExcelColumnTest {
    public static void main(String[] args) {
        check(1, "A");
        check(2, "B");
        check(26, "Z");
        check(27, "AA");
        check(52, "AZ");
        check(53, "BA");
        check(702, "ZZ");
        check(703, "AAA");

        boolean threw = false;
        try {
            ExcelColumn.name(0);
        } catch (IllegalArgumentException e) {
            threw = true;
        }
        if (!threw) {
            throw new AssertionError("name(0) must throw IllegalArgumentException");
        }

        System.out.println("all tests passed");
    }

    static void check(int n, String expected) {
        String got = ExcelColumn.name(n);
        if (!expected.equals(got)) {
            throw new AssertionError("name(" + n + ") = " + got + ", expected " + expected);
        }
    }
}

