public final class ExcelColumnTest {
    public static void main(String[] args) {
        if (ExcelColumn.name(1).isEmpty()) {
            throw new AssertionError("name(1) must not be empty");
        }
        if (ExcelColumn.name(5).length() != 1) {
            throw new AssertionError("small n should be one letter");
        }
        if (!ExcelColumn.name(100).chars().allMatch(Character::isUpperCase)) {
            throw new AssertionError("names are uppercase letters");
        }
        boolean threw = false;
        try {
            ExcelColumn.name(-5);
        } catch (IllegalArgumentException e) {
            threw = true;
        }
        if (!threw) {
            throw new AssertionError("negative n must throw");
        }
        System.out.println("all tests passed");
    }
}
